import{_ as a,o as t,a as n,b as c}from"./app.DKoEZOcr.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"Utils API","link":"/api/Utils-API/Utils-API"},{"text":"原型注册与管理","link":"/api/Utils-API/prototype_register_management/prototype_register_management"},{"text":"OpParamDef","link":"/api/Utils-API/prototype_register_management/OpParamDef/OpParamDef"},{"text":"ValueDepend","link":"/api/Utils-API/prototype_register_management/OpParamDef/ValueDepend"}]},"headers":[],"relativePath":"api/Utils-API/prototype_register_management/OpParamDef/ValueDepend.md","filePath":"api/Utils-API/prototype_register_management/OpParamDef/ValueDepend.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"},{"level":3,"title":"配置前后的接口差异","slug":"配置前后的接口差异","link":"#配置前后的接口差异"},{"level":3,"title":"两种GetWorkspaceSize接口的适用场景","slug":"两种GetWorkspaceSize接口的适用场景","link":"#两种GetWorkspaceSize接口的适用场景"}],"lastUpdated":1786068033000}'),s={name:"api/Utils-API/prototype_register_management/OpParamDef/ValueDepend.md"};function o(p,e,l,i,h,d){return t(),n("div",null,[...e[0]||(e[0]=[c(`<div><article class="markdown-body"><h1>ValueDepend<span id="ZH-CN_TOPIC_0000002078492704"></span></h1><h2 id="功能说明">功能说明<span id="zh-cn_topic_0000001626329929_zh-cn_topic_0000001576875005_zh-cn_topic_0000001525424352_section36583473819"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>标识该输入是否为“数据依赖输入”，数据依赖输入是指在Tiling/InferShape等函数实现时依赖该输入的具体数据。该输入数据为host侧数据，开发者在Tiling函数/InferShape函数中可以通过TilingContext类的GetInputTensor/InferShapeContext类的GetInputTensor获取这个输入数据。</p><h2 id="函数原型">函数原型<span id="zh-cn_topic_0000001626329929_zh-cn_topic_0000001576875005_zh-cn_topic_0000001525424352_section13230182415108"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>OpParamDef &amp;ValueDepend(Option value_depend)
OpParamDef &amp;ValueDepend(Option value_depend, DependScope scope)
</code></pre></div><h2 id="参数说明">参数说明<span id="zh-cn_topic_0000001626329929_zh-cn_topic_0000001576875005_zh-cn_topic_0000001525424352_section75395119104"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><span id="zh-cn_topic_0000001626329929_zh-cn_topic_0000001576875005_zh-cn_topic_0000001575944081_table111938719446"></span></p><table><thead><tr><th>参数</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td><code>value_depend</code></td><td>输入</td><td><code>REQUIRED</code>：表示算子的输入必须是Const类型。在调用算子的<a href="../OpAICoreDef/SetCheckSupport.html">SetCheckSupport</a>时，会校验算子的输入是否是Const类型。若校验通过，则将此输入的值下发到算子；否则报错。<code>OPTIONAL</code>：表示算子的输入可以是Const类型，也可以不是Const类型。如果输入是Const类型，则将输入的值下发到算子，否则不下发。</td></tr><tr><td><code>scope</code></td><td>输入</td><td><code>ALL</code>：指在Tiling/InferShape等函数实现时都依赖该输入的具体数据，行为与调用单参数ValueDepend重载接口一致。<code>TILING</code>：指仅在Tiling时依赖Tensor的值，可以支持Tiling下沉。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<span id="zh-cn_topic_0000001626329929_zh-cn_topic_0000001576875005_zh-cn_topic_0000001525424352_section25791320141317"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>OpParamDef算子定义，OpParamDef请参考<a href="OpParamDef.html">OpParamDef</a>。</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000001626329929_zh-cn_topic_0000001576875005_zh-cn_topic_0000001525424352_section19165124931511"></span><a class="header-anchor" href="#约束说明">​</a></h2><p>仅支持对算子输入配置，输入的<a href="DataType.html">参数数据类型</a>可以配置为DT_FLOAT/DT_BOOL/DT_INT64/DT_UINT64/DT_INT32/DT_UINT32/DT_INT16/DT_UINT16/DT_INT8/DT_UINT8，且必须满足以下三种情况之一：</p><ol><li><p>输入的<a href="DataType.html">参数数据类型</a>配置全为DT_FLOAT，对应生成的输出类型aclFloatArray（aclnn数据类型）。</p></li><li><p>输入的<a href="DataType.html">参数数据类型</a>配置全为DT_BOOL，对应生成的输出类型aclBoolArray（aclnn数据类型）。</p></li><li><p>输入的<a href="DataType.html">参数数据类型</a>配置全为整数类型，即DT_INT64/DT_UINT64/DT_INT32/DT_UINT32/DT_INT16/DT_UINT16/DT_INT8/DT_UINT8，对应生成的输出类型aclIntArray（aclnn数据类型）。当数据类型配置含有DT_INT64以外的数据类型时，需要增加一组DT_INT64对应的输入/输出数据类型组合。</p></li></ol><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000001626329929_section320753512363"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>下面以AddCustom算子的输入y为例。配置前，y为普通Tensor输入：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>this-&gt;Input(&quot;y&quot;)
    .ParamType(REQUIRED)
    .DataType({ge::DT_FLOAT})
    .Format({ge::FORMAT_ND});
</code></pre></div><p>如果Tiling依赖y的具体数据，增加ValueDepend配置：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>this-&gt;Input(&quot;y&quot;)
    .ParamType(REQUIRED)
    .DataType({ge::DT_FLOAT})
    .Format({ge::FORMAT_ND})
    .ValueDepend(OPTIONAL, DependScope::TILING);
</code></pre></div><p>ValueDepend用于声明Tiling是否依赖输入y的具体值。配置后，当y的值在Host侧可获取时，系统会在GetWorkspaceSize阶段将该值提供给Tiling，使Tiling能够根据输入值计算Tiling参数和Workspace；未配置ValueDepend时，系统不会将y作为数据依赖输入向Tiling提供具体数据。</p><h3 id="配置前后的接口差异">配置前后的接口差异<span id="zh-cn_topic_0000001626329929_section_product_diff"></span><a class="header-anchor" href="#配置前后的接口差异">​</a></h3><p>配置前后生成的aclnn接口如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 无ValueDepend
aclnnStatus aclnnAddCustomGetWorkspaceSize(
    const aclTensor *x,
    const aclTensor *y,
    const aclTensor *out,
    ...);

// 有ValueDepend
aclnnStatus aclnnAddCustomGetWorkspaceSize(
    const aclTensor *x,
    const aclFloatArray *y,    // 关键差异：调用侧在Host侧提供y的具体数据，供Tiling使用
    const aclTensor *out,
    ...);

// 额外生成
aclnnStatus aclnnAddCustomTensorGetWorkspaceSize(
    const aclTensor *x,
    const aclTensor *y,
    const aclTensor *out,
    ...);
</code></pre></div><p><code>const aclFloatArray *y</code>是配置ValueDepend后的关键接口变化。调用<code>aclnnAddCustomGetWorkspaceSize</code>时，调用侧需要将y的具体值封装为aclFloatArray并在Host侧传入，使Tiling能够读取这些值。此处<code>const</code>只表示接口不会修改aclFloatArray，不表示编译期常量。</p><p>算子执行接口<code>aclnnAddCustom</code>保持不变。升级到配置ValueDepend后重新生成的算子包时，调用侧需要根据输入形式调整<code>GetWorkspaceSize</code>接口，并重新编译调用程序。</p><h3 id="两种GetWorkspaceSize接口的适用场景">两种GetWorkspaceSize接口的适用场景<span id="zh-cn_topic_0000001626329929_section_workspace_api"></span><a class="header-anchor" href="#两种GetWorkspaceSize接口的适用场景">​</a></h3><p>输入y的具体数据在Host侧已知时，使用<code>aclnnAddCustomGetWorkspaceSize</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>float yValues[] = {1.0f, 2.0f, 3.0f, 4.0f};
aclFloatArray *yArray = aclCreateFloatArray(yValues, 4);

aclnnStatus ret = aclnnAddCustomGetWorkspaceSize(
    xTensor, yArray, outTensor, &amp;workspaceSize, &amp;executor);
</code></pre></div><p>输入y是运行时普通Tensor时，使用<code>aclnnAddCustomTensorGetWorkspaceSize</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>aclnnStatus ret = aclnnAddCustomTensorGetWorkspaceSize(
    xTensor, yTensor, outTensor, &amp;workspaceSize, &amp;executor);
</code></pre></div><p>两个接口均用于创建executor，后续调用相同的算子执行接口：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>aclnnAddCustom(workspace, workspaceSize, executor, stream);
</code></pre></div><p>使用aclFloatArray时，在算子执行完成并同步执行流后释放该对象：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>aclDestroyFloatArray(yArray);
</code></pre></div></article></div>`,1)])])}const v=a(s,[["render",o]]);export{_ as __pageData,v as default};
